package com.mantou.salesdialer.contacts;
import android.content.Context;import android.util.AtomicFile;import java.io.*;import java.nio.charset.StandardCharsets;import org.json.*;
/** Engineering live-validation permit. Absent by default; never granted by enterprise login or rehearsal. */
final class EnterpriseLivePermit {
 private static final Object LOCK=new Object();
 private static JSONObject permit(Context c)throws Exception{AtomicFile f=new AtomicFile(new File(c.getFilesDir(),"enterprise-live-permit.json"));if(!f.getBaseFile().exists())throw new IllegalStateException("LIVE_CALLS_DISABLED");byte[] bytes=f.readFully();if(bytes.length>8192)throw new IllegalStateException("LIVE_PERMIT_INVALID");JSONObject p=new JSONObject(new String(bytes,StandardCharsets.UTF_8));long now=System.currentTimeMillis();Object max=p.get("maxAttempts");if((p.getInt("schema")==1?p.length()!=13:p.getInt("schema")!=2||p.length()!=15||!p.optBoolean("allowOutOfHours")||p.optString("requestId").length()<8||p.getJSONArray("targetIds").length()!=1||p.getLong("notAfter")-p.getLong("notBefore")>600000)||!(p.get("schema") instanceof Integer)||(p.getInt("schema")!=1&&p.getInt("schema")!=2)||!p.getString("purpose").equals("CONTROLLED_LIVE_VALIDATION")||!(max instanceof Integer)||p.getInt("maxAttempts")<1||p.getInt("maxAttempts")>10||!p.getString("signature").matches("[a-f0-9]{64}")||now<p.getLong("notBefore")||now>p.getLong("notAfter")||p.getLong("notAfter")-p.getLong("notBefore")>1800000)throw new IllegalStateException("LIVE_PERMIT_INVALID");return p;}
 static boolean outsideWindow(Context c,String queue){try{JSONObject p=permit(c);return p.getInt("schema")==2&&p.optBoolean("allowOutOfHours")&&p.getString("queueId").equals(queue)&&p.getString("deviceId").equals(EnterpriseSession.deviceId(c))&&p.getString("accountKey").equals(PilotPhoneRuntime.selectedAccount(c).key);}catch(Exception e){return false;}}
 static void ready(Context c,JSONObject status,JSONObject queue,String account)throws Exception{synchronized(LOCK){if(EnterpriseOperatorBatch.present(c)){EnterpriseOperatorBatch.ready(c,status,queue,account);return;}JSONObject p=permit(c),a=status.getJSONObject("actor");if(!status.getString("mode").equals("LIVE")||!p.getString("tenantId").equals(a.getString("tenantId"))||!p.getString("ownerId").equals(a.getString("userId"))||!p.getString("queueId").equals(queue.getString("id"))||!p.getString("deviceId").equals(EnterpriseSession.deviceId(c))||!p.getString("accountKey").equals(account))throw new IllegalStateException("LIVE_PERMIT_SCOPE_MISMATCH");if(used(c,p.getString("id"))>=p.getInt("maxAttempts"))throw new IllegalStateException("LIVE_CALLS_DISABLED");}}
 private static int used(Context c,String id)throws Exception{AtomicFile f=new AtomicFile(new File(c.getFilesDir(),"enterprise-live-use.json"));if(!f.getBaseFile().exists())return 0;JSONObject j=new JSONObject(new String(f.readFully(),StandardCharsets.UTF_8));if(j.length()!=2||!(j.get("used") instanceof Integer)||j.getInt("used")<0||j.getInt("used")>10)throw new IllegalStateException("LIVE_PERMIT_USE_INVALID");return j.getString("id").equals(id)?j.getInt("used"):0;}
 static void consume(Context c,JSONObject status,JSONObject queue,JSONObject claim,String account)throws Exception{synchronized(LOCK){if(EnterpriseOperatorBatch.present(c)){EnterpriseOperatorBatch.consume(c,status,queue,claim,account);return;}ready(c,status,queue,account);JSONObject p=permit(c);if(!p.getString("id").equals(claim.getString("permitId")))throw new IllegalStateException("LIVE_PERMIT_SCOPE_MISMATCH");String target=claim.getJSONObject("target").getString("id");boolean found=false;JSONArray ids=p.getJSONArray("targetIds");for(int i=0;i<ids.length();i++)if(ids.getString(i).equals(target))found=true;if(!found)throw new IllegalStateException("LIVE_PERMIT_SCOPE_MISMATCH");AtomicFile f=new AtomicFile(new File(c.getFilesDir(),"enterprise-live-use.json"));JSONObject use=new JSONObject().put("id",p.getString("id")).put("used",used(c,p.getString("id"))+1);FileOutputStream out=f.startWrite();try{out.write(use.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){f.failWrite(out);throw e;}}}
}
